struct Glass3d {
	vec4 color; // its colour; its alpha comes from the depth behind it
	float density; // the alpha is 1 - exp(-density * the distance the view goes through it)
	uint padding0;
	uint padding1;
	uint padding2;
};

// What the example's view gives the pipelines that read it
